#!/bin/bash\n\n# Deploy Linguafly to Cloudflare\n# This script builds and deploys the application to Cloudflare Workers + Pages\n\nset -e\n\necho \"🚀 Deploying Linguafly to Cloudflare...\"\necho \"\"\n\n# Colors\nGREEN='\\033[0;32m'\nBLUE='\\033[0;34m'\nYELLOW='\\033[1;33m'\nNC='\\033[0m' # No Color\n\n# Step 1: Check environment\necho -e \"${BLUE}Step 1: Checking environment...${NC}\"\nif [ ! -f \".env\" ]; then\n    echo -e \"${YELLOW}⚠️  .env file not found${NC}\"\n    echo \"Creating .env from .env.example...\"\n    cp .env.example .env\n    echo -e \"${YELLOW}⚠️  Please configure .env with your API key and retry${NC}\"\n    exit 1\nfi\necho -e \"${GREEN}✅ Environment configured${NC}\"\necho \"\"\n\n# Step 2: Install dependencies\necho -e \"${BLUE}Step 2: Installing dependencies...${NC}\"\nnpm ci --legacy-peer-deps\necho -e \"${GREEN}✅ Dependencies installed${NC}\"\necho \"\"\n\n# Step 3: Generate Cloudflare types\necho -e \"${BLUE}Step 3: Generating Cloudflare environment types...${NC}\"\nnpm run cf-typegen\necho -e \"${GREEN}✅ Types generated${NC}\"\necho \"\"\n\n# Step 4: Run type checking\necho -e \"${BLUE}Step 4: Type checking...${NC}\"\nnpm run type-check || echo -e \"${YELLOW}⚠️  Type check issues (non-blocking)${NC}\"\necho \"\"\n\n# Step 5: Run linting\necho -e \"${BLUE}Step 5: Linting...${NC}\"\nnpm run lint || echo -e \"${YELLOW}⚠️  Lint issues (non-blocking)${NC}\"\necho \"\"\n\n# Step 6: Build application\necho -e \"${BLUE}Step 6: Building application...${NC}\"\nnpm run build\necho -e \"${GREEN}✅ Build successful${NC}\"\necho \"\"\n\n# Step 7: Deploy to Cloudflare\necho -e \"${BLUE}Step 7: Deploying to Cloudflare...${NC}\"\nnpm run cf:deploy\necho -e \"${GREEN}✅ Deployment successful${NC}\"\necho \"\"\n\n# Step 8: Post-deployment verification\necho -e \"${BLUE}Step 8: Verifying deployment...${NC}\"\nsleep 5  # Wait for DNS propagation\n\nHEALTH_URL=\"https://linguafly.dev/health\"\necho \"Testing: $HEALTH_URL\"\n\nif curl -s \"$HEALTH_URL\" | jq . > /dev/null 2>&1; then\n    echo -e \"${GREEN}✅ Health check passed${NC}\"\nelse\n    echo -e \"${YELLOW}⚠️  Health check failed (DNS might not be propagated yet)${NC}\"\nfi\necho \"\"\n\n# Summary\necho -e \"${GREEN}🎉 Deployment completed!${NC}\"\necho \"\"\necho \"Next steps:\"\necho \"1. Verify API endpoints:\"\necho \"   curl https://linguafly.dev/health\"\necho \"   curl https://linguafly.dev/api/articles/count\"\necho \"\"\necho \"2. Configure database schema (if not done):\"\necho \"   wrangler d1 execute linguafly_db --file=./src/lib/db/schema.sql --remote\"\necho \"\"\necho \"3. Import articles:\"\necho \"   npx tsx scripts/bulk-import-articles.ts articles.jsonl\"\necho \"\"\necho \"4. Monitor deployment:\"\necho \"   wrangler tail\"\necho \"\"\n"